overlays.css:
[data-ui-scroll-progress] {
  position: fixed;
  left: 0;
  right: 0;
  height: var(--ui-sp-height, 2px);
  background: var(--ui-sp-track, transparent);
  z-index: var(--ui-sp-z, 60);
  pointer-events: none;
}

[data-ui-scroll-progress][data-position="top"] {
  top: 0;
}

[data-ui-scroll-progress][data-position="bottom"] {
  bottom: 0;
}

[data-ui-scroll-progress] > span {
  display: block;
  height: 100%;
  width: 100%;
  background: var(--ui-sp-color, #c4b59a);
  transform: scaleX(0);
  transform-origin: left center;
  will-change: transform;
}

[data-ui-scroll-progress][data-smooth="true"] > span {
  transition: transform 0.12s linear;
}

@media (prefers-reduced-motion: reduce) {
  [data-ui-scroll-progress] > span {
    transition: none;
  }
}

overlays.js:
(function () {
  var root = document.querySelector('[data-ui-scroll-progress]');
  if (!root) return;
  var bar = root.firstElementChild;
  if (!bar) return;

  var frame = 0;
  function paint() {
    frame = 0;
    var max = document.documentElement.scrollHeight - window.innerHeight;
    var ratio = max > 0 ? Math.min(1, Math.max(0, window.scrollY / max)) : 0;
    bar.style.transform = 'scaleX(' + ratio + ')';
  }
  function schedule() {
    if (!frame) frame = window.requestAnimationFrame(paint);
  }

  window.addEventListener('scroll', schedule, { passive: true });
  window.addEventListener('resize', schedule);
  paint();
})();
